-  //   shiftAmount   = 0b101 & 0b010 = 0b000 (no shift needed)
-  //   blockMask     = 0b110011 << 0 = 0b00110011
-  // Example2: freeVarMask = 0b101, ctaId = 0b111 (cta 7)
-  //   ~freeVarMask  = 0b010
