content.content:
1	#include "Dialect/TritonAMDGPU/IR/TargetFeatures.h"
2	
3	#include "mlir/IR/BuiltinAttributes.h"
4	#include "triton/Dialect/TritonGPU/IR/Dialect.h"
5	#include "llvm/ADT/STLExtras.h"
6	#include "llvm/ADT/StringRef.h"
7	
8	namespace mlir::triton::amdgpu {
9	
10	namespace {
11	struct GfxArch {
12	  unsigned major;
13	  unsigned minor;
14	  unsigned patch;
15	};
16	
17	std::optional<GfxArch> parseGfxArch(StringRef arch) {
18	  if (!arch.consume_front("gfx"))
19	    return std::nullopt;
20	
21	  if (arch.size() < 3)
22	    return std::nullopt;
23	
24	  unsigned patch;
25	  if (arch.take_back(1).getAsInteger(16, patch))
26	    return std::nullopt;
27	  arch = arch.drop_back();
28	
29	  unsigned minor;
30	  if (arch.take_back(1).getAsInteger(10, minor))
31	    return std::nullopt;
32	  arch = arch.drop_back();
33	
34	  unsigned major;
35	  if (arch.getAsInteger(10, major))
36	    return std::nullopt;
37	
38	  return GfxArch{major, minor, patch};
39	}
40	} // namespace
41	
42	TargetFeatures::TargetFeatures(std::optional<StringRef> arch)
43	    : TargetFeatures(arch.value_or("")) {}
44	
45	TargetFeatures::TargetFeatures(StringRef arch) : arch(arch.str()) {}
46	
47	TargetFeatures TargetFeatures::fromModuleOp(ModuleOp moduleOp) {
48	  auto targetAttr =
49	      moduleOp->getAttrOfType<StringAttr>(triton::gpu::AttrTargetName);
50	  if (!targetAttr)
51	    return TargetFeatures(StringRef());
52	
53	  StringRef targetName = targetAttr.getValue();
54	  assert(targetName.starts_with(kTargetPrefix) &&
55	         "expected target attribute to be prefixed with \"hip:\"");
56	
57	  return TargetFeatures(targetName.drop_front(sizeof(kTargetPrefix) - 1));
58	}
59	
60	StringRef TargetFeatures::getArch() const { return arch; }
61	
62	ISAFamily TargetFeatures::getISAFamily() const {
63	  std::optional<GfxArch> gfxArch = parseGfxArch(arch);
64	  if (!gfxArch)
65	    return ISAFamily::Unknown;
66	  auto [major, minor, patch] = *gfxArch;
67	
68	  // See https://llvm.org/docs/AMDGPUUsage.html#processors for how to
69	  // categorize the following target gfx architectures. Parse the gfx number
70	  // directly here instead of depending on LLVM's target parser.
71	  if (major == 12 && minor == 5)
72	    return ISAFamily::GFX1250;
73	
74	  // CDNA ISA cases.
75	  if (major == 9) {
76	    if (minor == 5 && patch == 0)
77	      return ISAFamily::CDNA4;
78	    if (minor == 4 && patch == 2)
79	      return ISAFamily::CDNA3;
80	    if (minor == 0 && patch == 10)
81	      return ISAFamily::CDNA2;
82	    if (minor == 0 && patch == 8)
83	      return ISAFamily::CDNA1;
84	    if (minor == 0 && patch == 6)
85	      return ISAFamily::GCN5_1;
86	  }
87	
88	  // RDNA ISA cases.
89	  if (major == 12 && minor == 0)
90	    return ISAFamily::RDNA4;
91	  if (major == 11 && minor == 7)
92	    return ISAFamily::RDNA4m;
93	  if (major == 11)
94	    return ISAFamily::RDNA3;
95	  if (major == 10 && minor == 3)
96	    return ISAFamily::RDNA2;
97	  if (major == 10 && minor == 1)
98	    return ISAFamily::RDNA1;
99	
100	  return ISAFamily::Unknown;
101	}
102	
103	bool TargetFeatures::isCDNA() const {
104	  return mlir::triton::amdgpu::isCDNA(getISAFamily());
105	}
106	
107	bool TargetFeatures::isRDNA() const {
108	  return mlir::triton::amdgpu::isRDNA(getISAFamily());
109	}
110	
111	bool TargetFeatures::isCDNA3() const {
112	  return getISAFamily() == ISAFamily::CDNA3;
113	}
114	
115	bool TargetFeatures::isCDNA4() const {
116	  return getISAFamily() == ISAFamily::CDNA4;
117	}
118	
119	bool TargetFeatures::isGFX1250() const {
120	  return getISAFamily() == ISAFamily::GFX1250;
121	}
122	
123	int TargetFeatures::getWarpSize() const {
124	  switch (getISAFamily()) {
125	  case ISAFamily::GCN5_1:
126	  case ISAFamily::CDNA1:
127	  case ISAFamily::CDNA2:
128	  case ISAFamily::CDNA3:
129	  case ISAFamily::CDNA4:
130	    return 64;
131	  default:
132	    return 32;
133	  }
134	}
135	
136	bool TargetFeatures::supportsWaveId() const {
137	  return getISAFamily() == ISAFamily::RDNA4 ||
138	         getISAFamily() == ISAFamily::GFX1250;
139	}
140	
141	int TargetFeatures::getSharedMemorySize() const {
142	  // Should return the maximum capacity in bytes.
143	  switch (getISAFamily()) {
144	  case ISAFamily::GFX1250:
145	    return 320 * 1024;
146	  case ISAFamily::CDNA4:
147	    return 160 * 1024;
148	  default:
149	    return 64 * 1024;
150	  }
151	}
152	
153	size_t TargetFeatures::getSharedMemoryPartitionSize() const {
154	  switch (getISAFamily()) {
155	  case ISAFamily::GFX1250:
156	    return 64 * 1024;
157	  default:
158	    // No partitioning on other targets.
159	    return 0;
160	  }
161	}
162	
163	std::optional<TargetFeatures::LDSTransLoadParams>
164	TargetFeatures::queryLDSTransLoadParams(int bitWidth) const {
165	  auto isaFamily = getISAFamily();
166	  // Determine LDSTrans version: V1 (CDNA4), V2 (GFX1250).
167	  enum { V1, V2, NONE } version = NONE;
168	  if (isaFamily == ISAFamily::CDNA4) {
169	    version = V1;
170	  } else if (isaFamily == ISAFamily::GFX1250) {
171	    version = V2;
172	  }
173	
174	  if (version == NONE || !llvm::is_contained({16, 8, 4, 6}, bitWidth))
175	    return std::nullopt;
176	
177	  unsigned numLanesInShuffleGroup = getWarpSize() / 4;
178	
179	  auto ldsTransParams = [&](unsigned instBitWidth,
180	                            TileKind kind) -> LDSTransLoadParams {
181	    return {numLanesInShuffleGroup, instBitWidth, instBitWidth / bitWidth,
182	            kind};
183	  };
184	
185	  switch (version) {
186	  case V1:
187	    return ldsTransParams(64, TileKind::Standard);
188	  case V2:
189	    if (bitWidth == 8)
190	      return ldsTransParams(64, TileKind::DoubleContiguity);
191	    return ldsTransParams(128, TileKind::Standard);
192	  default:
193	    return std::nullopt;
194	  }
195	}
196	
197	bool TargetFeatures::supportsDirectToLdsScatter() const { return isGFX1250(); }
198	
199	bool TargetFeatures::supportsDirectToLdsLoadBitWidth(int bitWidth) const {
200	  switch (getISAFamily()) {
201	  case ISAFamily::CDNA3:
202	    // Disable 8 and 16 bits because they get extended to 32 bit.
203	    return llvm::is_contained({32, /*16, 8*/}, bitWidth);
204	  case ISAFamily::CDNA4:
205	    // Disable 8, 16, 96 bits because they get extended to 32/128 bit.
206	    return llvm::is_contained({128, /*96, */ 32, /*16, 8*/}, bitWidth);
207	  case ISAFamily::GFX1250:
208	    // Disable 8, 16 bits because they get extended to 32 bit and therefore
209	    // overwrite. 96 is not a pow2 and generally not useful in Triton.
210	    return llvm::is_contained({128, 64, /*96, */ 32, /*16, 8*/}, bitWidth);
211	  default:
212	    break;
213	  }
214	
215	  return false;
216	}
217	
218	bool TargetFeatures::supportsDirectFromLdsStoreBitWidth(int bitWidth) const {
219	  if (getISAFamily() == ISAFamily::GFX1250) {
220	    return llvm::is_contained({128, 64, 32, 8}, bitWidth);
221	  }
222	  return false;
223	}
