382	//   ctaMask = groupMask << groupOffset
383	// where:
384	//   - groupMask: Covers all 2^k CTAs in the group (k = number of free bits)
385	//   - groupOffset: Starting position of this group, determined by fixed bits
386	// As an example suppose we have 8 CTAs and freeVarMask = 0b101 (bits 0,2 free).
387	// This creates 2 groups of 4 CTAs each:
388	//   - Group 0: CTAs {0,1,4,5} (fixed bits = 0b000)
389	//   - Group 1: CTAs {2,3,6,7} (fixed bits = 0b010)
390	// For CTA 5 (0b101): groupOffset = 0b101 & 0b010 = 0 => ctaMask = 0b00110011
391	// For CTA 7 (0b111): groupOffset = 0b111 & 0b010 = 2 => ctaMask = 0b11001100
392	// If the group does not fit into `maxMaskPopcount` mask bits it is split into
393	// equally sized subgroups, see below.
394	Value emitCtaMulticastMask(RewriterBase &rewriter, Location loc, Value groupId,
395	                           const LinearLayout &regLayout,
396	                           unsigned maxMaskPopcount) {
397	  TritonLLVMOpBuilder b(loc, rewriter);
398	
399	  auto kBlock = StringAttr::get(rewriter.getContext(), "block");
400	  auto freeVarMask = regLayout.getFreeVariableMasks()[kBlock];
401	
402	  // If there are no free bits we do not share any data with other CTAs
403	  if (freeVarMask == 0) {
404	    return Value();
405	  }
406	
407	  assert(maxMaskPopcount > 0 && "expected a non-zero multicast mask limit");
408	
409	  // A communication group spans 2^(number of free bits) CTAs, so we can only
410	  // keep floor(log2(limit)) free bits. Dropping the highest free bits turns
411	  // them into subgroup selectors.
412	  // Example: freeVarMask = 0b1101 describes CTAs {0,1,4,5,8,9,12,13}; with a
413	  // limit of 5 we keep bits 0 and 2 so bit 3 selects {0,1,4,5} or {8,9,12,13}.
414	  int maxFreeBits = llvm::Log2_32(maxMaskPopcount);
415	  int multicastFreeVarMask = freeVarMask;
416	  while (llvm::popcount<uint32_t>(multicastFreeVarMask) > maxFreeBits)
417	    multicastFreeVarMask ^= llvm::bit_floor<uint32_t>(multicastFreeVarMask);
418	
419	  if (multicastFreeVarMask != freeVarMask) {
420	    unsigned numSharingCTAs = 1u << llvm::popcount<uint32_t>(freeVarMask);
421	    unsigned numMulticastCTAs = 1u << maxFreeBits;
422	    emitRemark(loc) << "Multicast group contains " << numSharingCTAs
423	                    << " workgroups, exceeding the hardware limit of "
424	                    << maxMaskPopcount << " set mask bits; splitting it into "
425	                    << "subgroups of " << numMulticastCTAs
426	                    << " workgroups. A cluster layout sharing data "
427	                    << "among at most " << numMulticastCTAs
428	                    << " workgroups may perform better.";
429	  }
430	
431	  // Construct the groupMask with 1s at all positions representing CTAs in the
432	  // (sub)group. We start with 0b1 and iterate over the retained free bits. For
433	  // every retained bit at position k, we copy the current pattern 2^k positions
434	  // higher.
435	  // Example for multicastFreeVarMask = 0b101, x = non determined yet:
436	  //   Initial:              groupMask = 0bxxxxxxx1 (positions {0})
437	  //   Bit 0 (retained):     groupMask = 0bxxxxxx11 (positions {0,1})
438	  //   Bit 1 (not retained): groupMask = 0bxxxx0011 (positions {0,1})
439	  //   Bit 2 (retained):     groupMask = 0b00110011 (positions {0,1,4,5})
440	  int groupMask = 1;
441	  for (int log2 = 0; log2 < regLayout.getInDimSizeLog2(kBlock); log2++) {
442	    if (!(multicastFreeVarMask & (1 << log2)))
443	      continue;
444	    groupMask = groupMask | (groupMask << (1 << log2));
445	  }
446	  // If all bits are retained we broadcast to all CTAs so return the group mask.
447	  if (multicastFreeVarMask == regLayout.getInDimSize(kBlock) - 1) {
448	    return b.i32_val(groupMask);
449	  }
450	  // The bits not retained (non-free bits plus subgroup selectors) set in the
451	  // ctaId determine the group offset. For every such bit set at position k, we
452	  // shift the groupMask by 2^k positions. This can be conveniently computed by
453	  // masking the ctaId with the inverse of multicastFreeVarMask. Note that this
454	  // never carries into a retained position because the shift amount and the
455	  // groupMask cover disjoint bits.
456	  // Example1: multicastFreeVarMask = 0b101
457	  //   ~multicastFreeVarMask = 0b010
458	  //   shiftAmount           = 0b101 & 0b010 = 0b000 (no shift needed)
459	  //   blockMask             = 0b110011 << 0 = 0b00110011
460	  // Example2: multicastFreeVarMask = 0b101, ctaId = 0b111 (cta 7)
461	  //   ~multicastFreeVarMask = 0b010
462	  //   shiftAmount           = 0b111 & 0b010 = 0b010 (shift by 2)
463	  //   blockMask             = 0b110011 << 2 = 0b11001100
464	  Value shiftAmount = b.and_(groupId, b.i32_val(~multicastFreeVarMask));
465	  Value ctaMask = b.shl(b.i32_val(groupMask), shiftAmount);
466	  return ctaMask;
467	}
468	
469	Value llLoad(RewriterBase &rewriter, Location loc, Value ptr, Type elemTy,
470	             Value pred, Value falseVal, Value multicastMask,
471	             triton::CacheModifier cm, bool forceNoAliasAsyncLoads) {
472	  return triton::amdgpu::MaskedLoadOp::create(rewriter, loc, elemTy, ptr, pred,
473	                                              falseVal, multicastMask, cm,
474	                                              forceNoAliasAsyncLoads)

